"use client";

import { useState, useEffect } from "react";
import axios from "axios";
import { useNavigate } from "react-router-dom";
import { AlertCircle, Loader2, Plus, X, Edit, Trash, RefreshCw, Download } from "lucide-react";
import Layout from "../../Layout";
import * as XLSX from "xlsx";

export default function ManageSortie() {
  const navigate = useNavigate();
  const [products, setProducts] = useState([]);
  const [sortieHistory, setSortieHistory] = useState([]);
  const [isLoading, setIsLoading] = useState(true);
  const [error, setError] = useState("");
  const [selectedSortieProducts, setSelectedSortieProducts] = useState(null);
  const [selectedDay, setSelectedDay] = useState("");
  const [selectedMonth, setSelectedMonth] = useState("");
  const [selectedYear, setSelectedYear] = useState("");
  const [searchChef, setSearchChef] = useState("");

  useEffect(() => {
    fetchData();
  }, []);

  const fetchData = async () => {
    setIsLoading(true);
    setError("");
    const token = localStorage.getItem("token");

    try {
      const [productsRes, sortieRes] = await Promise.all([
        axios.get(`${process.env.REACT_APP_API_URL}/api/products`, { headers: { Authorization: `Bearer ${token}` } }),
        axios.get(`${process.env.REACT_APP_API_URL}/api/sorties`, { headers: { Authorization: `Bearer ${token}` } }),
      ]);
      setProducts(productsRes.data);
      setSortieHistory(sortieRes.data);
    } catch (err) {
      setError(err.response?.data?.message || "Erreur lors du chargement des données");
    } finally {
      setIsLoading(false);
    }
  };

  const filteredSorties = sortieHistory.filter((sortie) => {
    const sortieDate = new Date(sortie.date);
    const chefName = sortie.chefName?.toLowerCase() || "";

    return (
      (!selectedDay || sortieDate.getDate().toString() === selectedDay) &&
      (!selectedMonth || (sortieDate.getMonth() + 1).toString() === selectedMonth) &&
      (!selectedYear || sortieDate.getFullYear().toString() === selectedYear) &&
      (!searchChef || chefName.includes(searchChef.toLowerCase()))
    );
  });

  const days = Array.from({ length: 31 }, (_, i) => i + 1);
  const months = Array.from({ length: 12 }, (_, i) => i + 1);
  const years = Array.from(
    new Set(sortieHistory.map(sortie => new Date(sortie.date).getFullYear()))
  ).sort();

  const handleEditSortie = (sortieId) => {
    navigate(`/EditSortie/${sortieId}`);
  };

  const handleDeleteSortie = async (sortieId) => {
    if (window.confirm("Voulez-vous vraiment supprimer cette sortie ?")) {
      const token = localStorage.getItem("token");
      try {
        await axios.delete(`${process.env.REACT_APP_API_URL}/api/sorties/${sortieId}`, {
          headers: { Authorization: `Bearer ${token}` },
        });
        fetchData();
      } catch (err) {
        setError(err.response?.data?.message || "Erreur lors de la suppression de la sortie");
      }
    }
  };

  const exportToExcel = () => {
    const data = sortieHistory.map((sortie) => ({
      Date: new Date(sortie.date).toLocaleDateString('fr-FR'),
      "Nom du Chef": sortie.chefName || "N/A",
      Produits: sortie.products?.length > 0
        ? sortie.products.map(p => `${p.productName}: ${p.quantity}`).join(", ")
        : "Aucun",
    }));

    const worksheet = XLSX.utils.json_to_sheet(data);
    const workbook = XLSX.utils.book_new();
    XLSX.utils.book_append_sheet(workbook, worksheet, "Sorties");

    // Auto-size columns
    const colWidths = Object.keys(data[0]).map((key, i) => ({
      wch: Math.max(
        key.length,
        ...data.map(row => String(row[key]).length)
      )
    }));
    worksheet['!cols'] = colWidths;

    XLSX.writeFile(workbook, `Sorties_${new Date().toLocaleDateString('fr-FR').replace(/\//g, '-')}.xlsx`);
  };

  const openProductsModal = (sortie) => setSelectedSortieProducts(sortie);
  const closeProductsModal = () => setSelectedSortieProducts(null);

  return (
    <Layout>
      <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-8">
        <div className="bg-white rounded-2xl shadow-xl overflow-hidden border border-[#C8A45D/30]/50">
          <div className="bg-gradient-to-r from-[#00717F] to-[#C8A45D] text-white p-6">
            <div className="flex flex-col sm:flex-row justify-between items-start sm:items-center gap-4">
              <h1 className="text-2xl font-bold">Gestion des Sorties</h1>
              <div className="flex gap-4">
                <button
                  onClick={fetchData}
                  className="px-4 py-2 bg-white text-[#00717F] rounded-lg flex items-center gap-2 hover:bg-[#C8A45D/20] transition-colors"
                >
                  <RefreshCw className="h-4 w-4" /> Rafraîchir
                </button>
                <button
                  onClick={() => navigate("/CreateSortie")}
                  className="px-4 py-2 bg-white text-[#00717F] rounded-lg flex items-center gap-2 hover:bg-[#C8A45D/20] transition-colors"
                >
                  <Plus className="h-4 w-4" /> Créer une Sortie
                </button>
                <button
                  onClick={exportToExcel}
                  className="px-4 py-2 bg-white text-[#00717F] rounded-lg flex items-center gap-2 hover:bg-[#C8A45D/20] transition-colors"
                >
                  <Download className="h-4 w-4" /> Exporter vers Excel
                </button>
              </div>
            </div>
          </div>

          {error && (
            <div className="p-4 mx-6 my-4 bg-red-50 border-l-4 border-red-500 flex items-center gap-3">
              <AlertCircle className="h-5 w-5 text-red-500" />
              <p className="text-red-700">{error}</p>
            </div>
          )}

          <div className="p-6 border-b border-[#C8A45D/30]/50">
            <h2 className="text-xl font-semibold text-[#00717F] mb-4">Recherche</h2>
            <div className="flex flex-col sm:flex-row gap-4">
              <select
                value={selectedDay}
                onChange={(e) => setSelectedDay(e.target.value)}
                className="px-4 py-2 border border-gray-300 rounded-md focus:outline-none focus:ring-2 focus:ring-[#00717F] focus:border-transparent w-full sm:w-1/5"
              >
                <option value="">Tous les jours</option>
                {days.map((day) => (
                  <option key={day} value={day}>
                    {day}
                  </option>
                ))}
              </select>
              <select
                value={selectedMonth}
                onChange={(e) => setSelectedMonth(e.target.value)}
                className="px-4 py-2 border border-gray-300 rounded-md focus:outline-none focus:ring-2 focus:ring-[#00717F] focus:border-transparent w-full sm:w-1/5"
              >
                <option value="">Tous les mois</option>
                {months.map((month) => (
                  <option key={month} value={month}>
                    {new Date(0, month - 1).toLocaleString('fr-FR', { month: 'long' })}
                  </option>
                ))}
              </select>
              <select
                value={selectedYear}
                onChange={(e) => setSelectedYear(e.target.value)}
                className="px-4 py-2 border border-gray-300 rounded-md focus:outline-none focus:ring-2 focus:ring-[#00717F] focus:border-transparent w-full sm:w-1/5"
              >
                <option value="">Toutes les années</option>
                {years.map((year) => (
                  <option key={year} value={year}>
                    {year}
                  </option>
                ))}
              </select>
              <input
                type="text"
                value={searchChef}
                onChange={(e) => setSearchChef(e.target.value)}
                className="px-4 py-2 border border-gray-300 rounded-md focus:outline-none focus:ring-2 focus:ring-[#00717F] focus:border-transparent w-full sm:w-2/5"
                placeholder="Rechercher par nom du chef..."
              />
            </div>
          </div>

          {isLoading ? (
            <div className="flex justify-center items-center h-64">
              <Loader2 className="h-10 w-10 text-[#00717F] animate-spin" />
            </div>
          ) : (
            <div className="p-6">
              <h2 className="text-xl font-semibold text-[#00717F] mb-4">Historique des Sorties</h2>
              <div className="overflow-x-auto border border-[#C8A45D/30]/50 rounded-lg shadow-sm">
                <table className="min-w-full divide-y divide-[#C8A45D/30]">
                  <thead className="bg-[#F5F6FA] sticky top-0 z-10 shadow-sm">
                    <tr className="text-[#00717F]">
                      <th className="px-6 py-4 text-left text-xs font-semibold uppercase tracking-wider">Date</th>
                      <th className="px-6 py-4 text-left text-xs font-semibold uppercase tracking-wider">Chef</th>
                      <th className="px-6 py-4 text-left text-xs font-semibold uppercase tracking-wider">Produits</th>
                      <th className="px-6 py-4 text-left text-xs font-semibold uppercase tracking-wider">Actions</th>
                    </tr>
                  </thead>
                  <tbody className="bg-white divide-y divide-[#C8A45D/30]/30">
                    {filteredSorties.length === 0 ? (
                      <tr>
                        <td colSpan={5} className="py-12 text-center text-gray-500">
                          <X className="h-12 w-12 mx-auto mb-2 text-gray-400" />
                          Aucune sortie trouvée
                        </td>
                      </tr>
                    ) : (
                      filteredSorties.map((sortie) => (
                        <tr key={sortie._id} className="hover:bg-[#F5F6FA]/50 transition-colors duration-200">
                          <td className="px-6 py-4 text-sm text-gray-900 whitespace-nowrap">
                            {new Date(sortie.date).toLocaleDateString('fr-FR')}
                          </td>
                          <td className="px-6 py-4 text-sm text-gray-900 whitespace-nowrap">
                            {sortie.chefName || "N/A"}
                          </td>
                          <td className="px-6 py-4 text-sm text-gray-700">
                            {sortie.products?.length > 0
                              ? sortie.products.map(p => `${p.productName}: ${p.quantity}`).join(", ")
                              : "Aucun"}
                          </td>

                          <td className="px-6 py-4 text-sm whitespace-nowrap">
                            <div className="flex gap-4">
                              <button
                                onClick={() => handleEditSortie(sortie._id)}
                                className="text-yellow-600 hover:text-yellow-800 flex items-center gap-1 transition-colors"
                                aria-label="Modifier la sortie"
                              >
                                <Edit className="h-4 w-4" /> Modifier
                              </button>
                              <button
                                onClick={() => handleDeleteSortie(sortie._id)}
                                className="text-red-600 hover:text-red-800 flex items-center gap-1 transition-colors"
                                aria-label="Supprimer la sortie"
                              >
                                <Trash className="h-4 w-4" /> Supprimer
                              </button>
                            </div>
                          </td>
                        </tr>
                      ))
                    )}
                  </tbody>
                </table>
              </div>
            </div>
          )}
        </div>

        {selectedSortieProducts && (
          <div className="fixed inset-0 bg-black/50 backdrop-blur-sm flex justify-center items-center z-50 p-4">
            <div className="max-w-md w-full bg-white rounded-xl shadow-xl overflow-hidden animate-in zoom-in-95 duration-200">
              <div className="bg-gradient-to-r from-amber-50 to-amber-100 border-b relative p-6">
                <button
                  onClick={closeProductsModal}
                  className="absolute right-4 top-4 rounded-full p-1.5 bg-white/90 text-zinc-500 hover:text-zinc-700 transition-colors"
                  aria-label="Fermer la modale"
                >
                  <X className="h-5 w-5" />
                </button>
                <h2 className="text-2xl font-bold text-[#00717F]">Produits de la Sortie</h2>
              </div>
              <div className="p-6 max-h-96 overflow-y-auto">
                {selectedSortieProducts.products && selectedSortieProducts.products.length > 0 ? (
                  <ul className="space-y-4">
                    {selectedSortieProducts.products.map((product, index) => (
                      <li key={index} className="text-gray-900 text-sm font-medium border-b border-gray-200 pb-2">
                        {product.productName} - Quantité: {product.quantity}
                      </li>
                    ))}
                  </ul>
                ) : (
                  <p className="text-gray-500 text-sm">Aucun produit associé à cette sortie.</p>
                )}
              </div>
              <div className="p-6 bg-zinc-50 border-t flex justify-end">
                <button
                  onClick={closeProductsModal}
                  className="px-4 py-2 bg-white border border-zinc-300 rounded-lg text-zinc-700 hover:bg-zinc-50 transition-colors text-sm font-medium"
                >
                  Fermer
                </button>
              </div>
            </div>
          </div>
        )}
      </div>
    </Layout>
  );
}
